// Round-robin scheduler — distribuir trabajo entre workers
function* roundRobin(workers) {
  let i = 0;
  while (true) {
    yield workers[i % workers.length];
    i++;
  }
}

const workers = ['worker-1', 'worker-2', 'worker-3'];
const scheduler = roundRobin(workers);

const tareas = ['tarea-A', 'tarea-B', 'tarea-C', 'tarea-D', 'tarea-E'];

const asignaciones = tareas.map(tarea => ({
  tarea,
  worker: scheduler.next().value,
}));

console.log(asignaciones);
// A→worker-1, B→worker-2, C→worker-3, D→worker-1, E→worker-2

// Generador como acumulador (yield recibe valores)
// next(valor) envía un valor al generador
function* acumulador(valorInicial = 0) {
  let total = valorInicial;
  while (true) {
    const entrada = yield total; // yield retorna el total Y recibe la siguiente entrada
    if (entrada === null) break;
    total += entrada;
  }
  return total;
}

const acc = acumulador(100);
acc.next();       // Inicializa: { value: 100, done: false }
acc.next(50);     // Total: 150
acc.next(30);     // Total: 180
acc.next(20);     // Total: 200

console.log(acc.next(null)); // { value: 200, done: true } — termina

