function* semaforo() {
  const ciclo = [
    { color: 'rojo',               duracion: 30, mensaje: 'Espere' },
    { color: 'verde',              duracion: 20, mensaje: 'Camine' },
    { color: 'verde parpadeante', duracion: 5,  mensaje: 'Precaución' },
  ];

  while (true) {
    for (const estado of ciclo) {
      yield estado;
    }
  }
}

function tomarEstados(gen, n) {
  const estados = [];
  for (const estado of gen) {
    estados.push(estado);
    if (estados.length >= n) break;
  }
  return estados;
}

const estados6 = tomarEstados(semaforo(), 6);
